<script setup>
import { onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useAppState } from '../../composables/useAppState'

const { selectedProfile, loadPublicProfile, go, toast } = useAppState()
const route = useRoute()
const router = useRouter()
const loadError = ref('')

// The student id is kept in the URL (?id=...) so the page still works after a refresh.
onMounted(async () => {
    const id = route.query.id || selectedProfile.value?.id
    if (!id) return go('student/discover')
    if (!route.query.id) router.replace({ query: { id } })
    try {
        await loadPublicProfile(id)
    } catch (error) {
        loadError.value = error.message
    }
})
</script>

